import{_ as n,o as s,c as e,a2 as l}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"Development and Contribution Guide","description":"","frontmatter":{},"headers":[],"relativePath":"instruction.md","filePath":"instruction.md"}'),p={name:"instruction.md"};function i(r,a,t,o,c,d){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="development-and-contribution-guide" tabindex="-1">Development and Contribution Guide <a class="header-anchor" href="#development-and-contribution-guide" aria-label="Permalink to &quot;Development and Contribution Guide&quot;">​</a></h1><p>Dokumen ini menjelaskan cara membangun, menjalankan, memahami proyek, dan berkontribusi pada Rupa.</p><h2 id="_1-memulai" tabindex="-1">1. Memulai <a class="header-anchor" href="#_1-memulai" aria-label="Permalink to &quot;1. Memulai&quot;">​</a></h2><p>Clone repository Rupa dan masuk ke root project. Dari sana, jalur utama untuk development adalah <code>build.sh</code>.</p><p>Build dalam mode development:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">DEV_MODE</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">1</span><span style="color:#B392F0;"> ./build.sh</span><span style="color:#9ECBFF;"> debug</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Binary hasil build berada di:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>bin/rupa</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Jalankan Rupa dengan:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">./bin/rupa</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Untuk melihat command yang tersedia:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">DEV_MODE</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">1</span><span style="color:#B392F0;"> ./build.sh</span><span style="color:#79B8FF;"> --help</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>Makefile</code> tetap tersedia sebagai jalur build tambahan, tetapi <code>build.sh</code> digunakan sebagai jalur utama development.</p><h2 id="_2-syarat-yang-diperlukan" tabindex="-1">2. Syarat yang diperlukan <a class="header-anchor" href="#_2-syarat-yang-diperlukan" aria-label="Permalink to &quot;2. Syarat yang diperlukan&quot;">​</a></h2><h3 id="wajib" tabindex="-1">Wajib <a class="header-anchor" href="#wajib" aria-label="Permalink to &quot;Wajib&quot;">​</a></h3><ul><li>Compiler C yang kompatibel, umumnya <code>gcc</code></li><li>Bash</li><li>Utilitas dasar sistem Linux/POSIX</li></ul><h3 id="disarankan-untuk-development" tabindex="-1">Disarankan untuk development <a class="header-anchor" href="#disarankan-untuk-development" aria-label="Permalink to &quot;Disarankan untuk development&quot;">​</a></h3><ul><li><code>ccache</code> untuk mempercepat build ulang</li><li><code>bear</code> atau <code>intercept-build</code> untuk <code>compile_commands.json</code></li><li><code>clangd</code> untuk tooling editor</li><li><code>gdb</code> untuk debugging</li></ul><p>Contoh pada Debian:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#9ECBFF;"> apt</span><span style="color:#9ECBFF;"> update</span></span>
<span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#9ECBFF;"> apt</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> build-essential</span><span style="color:#9ECBFF;"> ccache</span><span style="color:#9ECBFF;"> bear</span><span style="color:#9ECBFF;"> clangd</span><span style="color:#9ECBFF;"> gdb</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Sesuaikan nama paket dengan distribusi atau environment yang digunakan.</p><h2 id="_3-cara-build-dan-test" tabindex="-1">3. Cara build dan test <a class="header-anchor" href="#_3-cara-build-dan-test" aria-label="Permalink to &quot;3. Cara build dan test&quot;">​</a></h2><p>Build development:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">DEV_MODE</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">1</span><span style="color:#B392F0;"> ./build.sh</span><span style="color:#9ECBFF;"> debug</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Jalankan test:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">DEV_MODE</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">1</span><span style="color:#B392F0;"> ./build.sh</span><span style="color:#9ECBFF;"> test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Jika ingin melakukan perubahan pada compiler atau syntax, jalankan test setelah perubahan dibuat.</p><p>Untuk perubahan yang lebih besar, gunakan urutan sederhana:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>ubah source</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>build</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>test</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>jalankan contoh secara langsung bila diperlukan</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Jangan hanya menganggap perubahan benar karena project berhasil dikompilasi. Build yang sukses tidak selalu berarti perilaku bahasa sudah benar.</p><h2 id="_4-memahami-struktur-project" tabindex="-1">4. Memahami struktur project <a class="header-anchor" href="#_4-memahami-struktur-project" aria-label="Permalink to &quot;4. Memahami struktur project&quot;">​</a></h2><p>Struktur direktori dan tanggung jawab setiap bagian project dijelaskan di:</p><p><a href="./structure.html">structure.md</a></p><p>Baca dokumen tersebut sebelum memindahkan file, membuat modul baru, atau mengubah batas tanggung jawab antar bagian sistem.</p><p>Secara umum, Rupa terdiri dari beberapa alur utama:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Source / REPL</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Lexer</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Processor</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Token</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Parser</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>AST</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Runtime</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>Setiap bagian memiliki tanggung jawab sendiri. Perubahan pada satu tahap tidak selalu harus menyebabkan perubahan pada seluruh tahap.</p><h2 id="_5-memahami-dan-menulis-syntax-rupa" tabindex="-1">5. Memahami dan menulis syntax Rupa <a class="header-anchor" href="#_5-memahami-dan-menulis-syntax-rupa" aria-label="Permalink to &quot;5. Memahami dan menulis syntax Rupa&quot;">​</a></h2><p>Dokumentasi syntax ditujukan dari sudut pandang pengguna bahasa.</p><p>Mulai dari:</p><p><a href="./syntax/">docs/syntax/</a></p><p>Setiap dokumen syntax berfokus pada tiga hal:</p><ol><li>Apa yang bisa ditulis?</li><li>Kapan digunakan?</li><li>Apa hasilnya?</li></ol><p>Contohnya:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/syntax/</span></span>
<span class="line"><span>├── assignment.md</span></span>
<span class="line"><span>├── function.md</span></span>
<span class="line"><span>├── if.md</span></span>
<span class="line"><span>├── loop.md</span></span>
<span class="line"><span>├── object.md</span></span>
<span class="line"><span>└── ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Jika ingin memahami bagaimana syntax tersebut dibentuk oleh sistem, bagaimana parser membaca construct, atau bagaimana bentuk AST-nya, lihat:</p><p><a href="./grammar/">docs/grammar/</a></p><p>Pembagiannya adalah:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/syntax/</span></span>
<span class="line"><span>└── Perspektif pengguna bahasa</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docs/grammar/</span></span>
<span class="line"><span>└── Perspektif desain bahasa dan sistem</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Jangan menggunakan implementasi C sebagai satu-satunya acuan untuk menentukan syntax resmi. Syntax yang didukung dan cara penggunaannya harus memiliki acuan di dokumentasi syntax.</p><h2 id="_6-sistem-memori-dan-gc" tabindex="-1">6. Sistem memori dan GC <a class="header-anchor" href="#_6-sistem-memori-dan-gc" aria-label="Permalink to &quot;6. Sistem memori dan GC&quot;">​</a></h2><p>Rupa memiliki sistem pengelolaan memori terpusat melalui <code>GarbageCollector</code>.</p><p>GC Rupa saat ini bekerja sebagai registry kepemilikan alokasi. Pointer yang dialokasikan atau didaftarkan ke GC disimpan dalam daftar internal sehingga dapat dibersihkan secara terpusat.</p><p>Alur sederhananya:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>gcinit()</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>alokasi melalui API GC</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>pointer didaftarkan ke GC</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>runtime menggunakan pointer</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>gcclean()</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>seluruh pointer terdaftar dibersihkan</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>API utama:</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">gcinit</span><span style="color:#E1E4E8;">(capacity);</span><span style="color:#6A737D;">              // Membuat konteks GC</span></span>
<span class="line"></span>
<span class="line"><span style="color:#B392F0;">gcmall</span><span style="color:#E1E4E8;">(size);</span><span style="color:#6A737D;">                  // malloc + register ke GC</span></span>
<span class="line"><span style="color:#B392F0;">gccalloc</span><span style="color:#E1E4E8;">(count, size);</span><span style="color:#6A737D;">         // calloc-like + register</span></span>
<span class="line"><span style="color:#B392F0;">gcrealloc</span><span style="color:#E1E4E8;">(ptr, size);</span><span style="color:#6A737D;">          // realloc sambil memperbarui registry</span></span>
<span class="line"><span style="color:#B392F0;">gcresize</span><span style="color:#E1E4E8;">(ptr, old, new);</span><span style="color:#6A737D;">       // resize + zero-initialize bagian baru</span></span>
<span class="line"></span>
<span class="line"><span style="color:#B392F0;">gcstrdup</span><span style="color:#E1E4E8;">(str);</span><span style="color:#6A737D;">                 // duplicate string yang dikelola GC</span></span>
<span class="line"><span style="color:#B392F0;">gcstrndup</span><span style="color:#E1E4E8;">(str, n);</span><span style="color:#6A737D;">             // duplicate string dengan panjang tertentu</span></span>
<span class="line"><span style="color:#B392F0;">gcarray</span><span style="color:#E1E4E8;">(count, size);</span><span style="color:#6A737D;">          // alokasi array</span></span>
<span class="line"></span>
<span class="line"><span style="color:#B392F0;">gcreg</span><span style="color:#E1E4E8;">(ptr);</span><span style="color:#6A737D;">                    // register pointer</span></span>
<span class="line"><span style="color:#B392F0;">gcremove</span><span style="color:#E1E4E8;">(ptr);</span><span style="color:#6A737D;">                 // hapus dari registry tanpa free</span></span>
<span class="line"><span style="color:#B392F0;">gcfree</span><span style="color:#E1E4E8;">(ptr);</span><span style="color:#6A737D;">                   // free pointer dan hapus dari registry</span></span>
<span class="line"><span style="color:#B392F0;">gcfind</span><span style="color:#E1E4E8;">(ptr);</span><span style="color:#6A737D;">                   // mencari pointer di registry</span></span>
<span class="line"></span>
<span class="line"><span style="color:#B392F0;">gcclean</span><span style="color:#E1E4E8;">();</span><span style="color:#6A737D;">                     // membersihkan seluruh pointer terdaftar</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h3 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><p>Aturan pentingnya adalah memahami siapa yang memiliki pointer.</p><p>Jika memori dibuat dengan:</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">void</span><span style="color:#F97583;"> *</span><span style="color:#E1E4E8;">data </span><span style="color:#F97583;">=</span><span style="color:#B392F0;"> gcmall</span><span style="color:#E1E4E8;">(size);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>pointer tersebut telah terdaftar pada GC. Jangan memperlakukannya sebagai alokasi biasa tanpa memperhatikan registry.</p><p>Khusus saat ukuran pointer berubah, gunakan:</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">data </span><span style="color:#F97583;">=</span><span style="color:#B392F0;"> gcrealloc</span><span style="color:#E1E4E8;">(data, new_size);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>bukan langsung:</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">data </span><span style="color:#F97583;">=</span><span style="color:#B392F0;"> realloc</span><span style="color:#E1E4E8;">(data, new_size);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Alasannya, <code>realloc()</code> dapat menghasilkan alamat baru. Jika registry GC masih menyimpan alamat lama, registry dan pointer aktual akan tidak sinkron.</p><p><code>gcrealloc()</code> memperbarui pointer di registry ketika alamat berubah.</p><h3 id="pembersihan-manual" tabindex="-1">Pembersihan manual <a class="header-anchor" href="#pembersihan-manual" aria-label="Permalink to &quot;Pembersihan manual&quot;">​</a></h3><p>Jika sebuah alokasi ingin dibersihkan sebelum seluruh runtime selesai:</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">gcfree</span><span style="color:#E1E4E8;">(data);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Jika pointer tidak lagi ingin dikelola GC tetapi tidak ingin langsung dibebaskan:</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">gcremove</span><span style="color:#E1E4E8;">(data);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Setelah pointer dihapus dari registry, ownership-nya harus ditangani oleh bagian lain. Jangan membiarkan pointer kehilangan pemilik yang jelas.</p><h3 id="prinsip-kontribusi-untuk-memori" tabindex="-1">Prinsip kontribusi untuk memori <a class="header-anchor" href="#prinsip-kontribusi-untuk-memori" aria-label="Permalink to &quot;Prinsip kontribusi untuk memori&quot;">​</a></h3><p>Sebelum menambahkan <code>malloc()</code>, <code>calloc()</code>, <code>realloc()</code>, atau <code>free()</code>, tanyakan:</p><ul><li>Siapa pemilik memori ini?</li><li>Berapa lama memori harus hidup?</li><li>Apakah memori ini harus terdaftar pada GC?</li><li>Siapa yang membebaskannya?</li><li>Apakah pointer dapat berubah alamat?</li></ul><p>Jangan mencampur alokasi biasa dan alokasi yang dikelola GC tanpa memahami ownership-nya.</p><h2 id="_7-cara-berkontribusi" tabindex="-1">7. Cara berkontribusi <a class="header-anchor" href="#_7-cara-berkontribusi" aria-label="Permalink to &quot;7. Cara berkontribusi&quot;">​</a></h2><p>Sebelum mengubah kode, tentukan terlebih dahulu masalah dan tahap sistem yang benar-benar terkait.</p><p>Contoh:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Syntax</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>docs/syntax/</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Lexer / Processor</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Token</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Parser / AST</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Runtime</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>Tidak semua perubahan harus melewati seluruh jalur tersebut.</p><h3 id="perubahan-syntax" tabindex="-1">Perubahan syntax <a class="header-anchor" href="#perubahan-syntax" aria-label="Permalink to &quot;Perubahan syntax&quot;">​</a></h3><p>Jika ingin menambah atau mengubah syntax:</p><ol><li>Baca <code>docs/syntax/*.md</code>.</li><li>Tentukan perilaku yang ingin didukung pengguna.</li><li>Periksa <code>docs/grammar/*.md</code> untuk dampaknya terhadap grammar dan sistem.</li><li>Ubah implementasi yang memang diperlukan.</li><li>Tambahkan atau perbarui test.</li><li>Jalankan build dan test.</li><li>Perbarui dokumentasi jika syntax resmi berubah.</li></ol><h3 id="perubahan-internal" tabindex="-1">Perubahan internal <a class="header-anchor" href="#perubahan-internal" aria-label="Permalink to &quot;Perubahan internal&quot;">​</a></h3><p>Untuk perubahan lexer, parser, AST, runtime, atau modul internal:</p><ol><li>Pahami alur data dan context yang sudah ada.</li><li>Temukan titik ownership dan tanggung jawab modul.</li><li>Ubah bagian yang relevan terlebih dahulu.</li><li>Hindari merombak bagian lain tanpa kebutuhan yang jelas.</li><li>Build dan test setelah perubahan.</li></ol><p>Struktur project yang ada lebih penting daripada memaksakan pola umum dari project lain. Perubahan struktur harus dilakukan karena memang menyelesaikan masalah arsitektur, bukan hanya karena terlihat lebih familiar.</p><h2 id="_8-sebelum-mengirim-perubahan" tabindex="-1">8. Sebelum mengirim perubahan <a class="header-anchor" href="#_8-sebelum-mengirim-perubahan" aria-label="Permalink to &quot;8. Sebelum mengirim perubahan&quot;">​</a></h2><p>Minimal lakukan:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">DEV_MODE</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">1</span><span style="color:#B392F0;"> ./build.sh</span><span style="color:#9ECBFF;"> debug</span></span>
<span class="line"><span style="color:#E1E4E8;">DEV_MODE</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">1</span><span style="color:#B392F0;"> ./build.sh</span><span style="color:#9ECBFF;"> test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Kemudian pastikan:</p><ol><li>Build berhasil.</li><li>Test terkait berhasil.</li><li>Perubahan menghasilkan perilaku yang memang diinginkan.</li><li>Context tidak bocor ke input atau construct berikutnya.</li><li>Ownership memori tetap jelas.</li><li>Dokumentasi diperbarui jika perilaku resmi berubah.</li><li>Perubahan tidak mencampurkan masalah yang tidak berkaitan.</li></ol><h2 id="_9-titik-awal" tabindex="-1">9. Titik awal <a class="header-anchor" href="#_9-titik-awal" aria-label="Permalink to &quot;9. Titik awal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Jenis pekerjaan</th><th>Mulai dari</th></tr></thead><tbody><tr><td>Memahami project</td><td><code>docs/structure.md</code></td></tr><tr><td>Memahami syntax</td><td><code>docs/syntax/*.md</code></td></tr><tr><td>Memahami grammar dan sistem</td><td><code>docs/grammar/*.md</code></td></tr><tr><td>Mengubah lexer</td><td><code>src/compiler/lexer/</code></td></tr><tr><td>Mengubah parser atau AST</td><td><code>src/compiler/parser/</code></td></tr><tr><td>Mengubah token</td><td><code>src/compiler/token/</code></td></tr><tr><td>Mengubah runtime</td><td><code>src/runtime/</code></td></tr><tr><td>Mengubah GC</td><td><code>src/runtime/gc/</code> dan <code>lib/runtime/gc/</code></td></tr><tr><td>Mengubah build</td><td><code>build.sh</code> dan <code>commands/</code></td></tr><tr><td>Menambah atau memperbarui test</td><td><code>tests/</code></td></tr></tbody></table><p>Jika tidak yakin harus mulai dari mana, mulai dari dokumentasi terlebih dahulu. Pahami apa yang seharusnya dilakukan sistem sebelum mengubah bagaimana sistem melakukannya.</p>`,98)])])}const m=n(p,[["render",i]]);export{b as __pageData,m as default};
